## Code Example

```javascript
// Pseudo: compute per-tenant slot allocation from CKNE and queue depth
function allocateSlots(tenants, totalSlots, baseline) {
  const weights = tenants.map(t => t.ckne * A + (baseline - t.queue) / baseline * B);
  const sum = weights.reduce((x, y) => x + y, 0);
  return tenants.map((t, i) => Math.max(t.minSlots, Math.floor((weights[i] / sum) * totalSlots)));
}
```

